using System.Collections.Concurrent;

namespace ResearchAgent.Tools;

/// <summary>
/// Thread-safe in-memory store for research notes.
/// </summary>
public sealed class Notebook
{
    private readonly ConcurrentBag<string> _notes = [];

    public void Add(string note) => _notes.Add(note);

    public IReadOnlyList<string> GetAll() => [.. _notes];

    public int Count => _notes.Count;
}

using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed partial class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient) => _httpClient = httpClient;

    [Description("Searches the web for the given query and returns a summary of results. " +
                 "Use this to find information on any topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            var results = ExtractSearchResults(html);

            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}");
            sb.AppendLine();

            foreach (var (title, snippet, resultUrl) in results.Take(5))
            {
                sb.AppendLine($"• {title}");
                if (!string.IsNullOrWhiteSpace(resultUrl))
                    sb.AppendLine($"  URL: {resultUrl}");
                if (!string.IsNullOrWhiteSpace(snippet))
                    sb.AppendLine($"  {snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Url)> ExtractSearchResults(string html)
    {
        var results = new List<(string, string, string)>();

        // Extract result links and snippets from DuckDuckGo lite HTML
        var linkMatches = ResultLinkPattern().Matches(html);
        var snippetMatches = SnippetPattern().Matches(html);

        for (int i = 0; i < linkMatches.Count && i < 8; i++)
        {
            var title = StripHtml(linkMatches[i].Groups[2].Value).Trim();
            var url = linkMatches[i].Groups[1].Value.Trim();
            var snippet = i < snippetMatches.Count
                ? StripHtml(snippetMatches[i].Groups[1].Value).Trim()
                : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add((title, snippet, url));
        }

        // Fallback: extract any text blocks if structured parsing found nothing
        if (results.Count == 0)
        {
            var cleanText = StripHtml(html);
            var lines = cleanText.Split('\n', StringSplitOptions.RemoveEmptyEntries)
                .Select(l => l.Trim())
                .Where(l => l.Length > 30)
                .Take(5)
                .ToList();

            foreach (var line in lines)
                results.Add((line[..Math.Min(80, line.Length)], line, ""));
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var text = HtmlTagPattern().Replace(html, " ");
        text = WebUtility.HtmlDecode(text);
        text = WhitespacePattern().Replace(text, " ");
        return text.Trim();
    }

    [GeneratedRegex("""<a[^>]+href="([^"]*)"[^>]*>(.*?)</a>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex ResultLinkPattern();

    [GeneratedRegex("""<td[^>]*class="result-snippet"[^>]*>(.*?)</td>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex SnippetPattern();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagPattern();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespacePattern();
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class NoteTakingTool
{
    private readonly Notebook _notebook;

    public NoteTakingTool(Notebook notebook) => _notebook = notebook;

    [Description("Saves a research note. Use this to record key findings, facts, or insights " +
                 "discovered during research. Call this multiple times to build up notes.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notebook.Add(note);
        return $"Note saved ({_notebook.Count} total).";
    }

    [Description("Retrieves all saved research notes. Use this to review what you've learned " +
                 "before writing a summary.")]
    public string GetNotes()
    {
        var notes = _notebook.GetAll();

        if (notes.Count == 0)
            return "No notes saved yet.";

        var lines = notes.Select((n, i) => $"{i + 1}. {n}");
        return $"Research notes ({notes.Count} total):\n{string.Join("\n", lines)}";
    }
}

