 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Hosting;
 using OpenAI;
 using ResearchAgent.Tools;

 var builder = Host.CreateApplicationBuilder(args);

 // --- Configuration -----------------------------------------------------------
 var apiKey = builder.Configuration["AI:ApiKey"]
     ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable or configure AI:ApiKey.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // --- Services ----------------------------------------------------------------
 builder.Services.AddHttpClient<WebSearchTool>();
 builder.Services.AddSingleton<Notebook>();
 builder.Services.AddSingleton<NoteTakingTool>();

 builder.Services.AddChatClient(sp =>
     new ChatClientBuilder(
             new OpenAI.OpenAIClient(apiKey)
                 .GetChatClient(modelId)
                 .AsIChatClient())
         .UseFunctionInvocation()
         .Build(sp));

 using var host = builder.Build();

 // --- Resolve tools -----------------------------------------------------------
 var chatClient = host.Services.GetRequiredService<IChatClient>();
 var searchTool = host.Services.GetRequiredService<WebSearchTool>();
 var noteTool = host.Services.GetRequiredService<NoteTakingTool>();
 var notebook = host.Services.GetRequiredService<Notebook>();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(searchTool.SearchWebAsync),
     AIFunctionFactory.Create(noteTool.AddNote),
     AIFunctionFactory.Create(noteTool.GetNotes),
 };

 // --- Prompt ------------------------------------------------------------------
 Console.Write("Enter a research topic: ");
 var topic = Console.ReadLine()?.Trim();
 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\n🔍 Researching: {topic}\n");

 var messages = new List<ChatMessage>
 {
     new(ChatRole.System, """
         You are a research agent. Investigate the given topic step-by-step:

         1. Search the web 2-3 times with varied queries to gather broad information.
         2. After each search, save key findings as notes using the add_note tool.
         3. Once you have enough information, call get_notes to review everything.
         4. Write a comprehensive, well-structured summary with sections and bullet points.

         Be thorough but concise. Cite sources when possible.
         """),
     new(ChatRole.User, $"Research the following topic and provide a detailed summary: {topic}"),
 };

 var options = new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
     Tools = tools,
 };

 // --- Agent loop (capped iterations) -----------------------------------------
 const int maxIterations = 15;

 for (int i = 0; i < maxIterations; i++)
 {
     ChatResponse response;
     try
     {
         response = await chatClient.GetResponseAsync(messages, options);
     }
     catch (Exception ex)
     {
         Console.Error.WriteLine($"\n⚠️  AI call failed: {ex.Message}");
         break;
     }

     messages.AddMessages(response);

     if (response.FinishReason != ChatFinishReason.ToolCalls)
     {
         Console.WriteLine("═══════════════════════════════════════════");
         Console.WriteLine("           RESEARCH SUMMARY");
         Console.WriteLine("═══════════════════════════════════════════\n");
         Console.WriteLine(response.Text);
         break;
     }

     Console.WriteLine($"  ⏳ Agent working... (step {i + 1})");

     if (i == maxIterations - 1)
     {
         Console.WriteLine("\n⚠️  Reached maximum iterations.");
     }
 }

 // --- Display collected notes -------------------------------------------------
 var notes = notebook.GetAll();
 if (notes.Count > 0)
 {
     Console.WriteLine("\n───────────────────────────────────────────");
     Console.WriteLine("           RESEARCH NOTES");
     Console.WriteLine("───────────────────────────────────────────");
     for (int i = 0; i < notes.Count; i++)
     {
         Console.WriteLine($"  {i + 1}. {notes[i]}");
     }
     Console.WriteLine();
 }

